create index knowledge_documents_active_version_idx on public.knowledge_documents(id,active_version_id);
drop policy administrator_documents on public.knowledge_documents;
drop policy administrator_versions on public.knowledge_versions;
drop policy chunks_admin on public.knowledge_chunks;
drop policy published_documents on public.knowledge_documents;
drop policy published_versions on public.knowledge_versions;
drop policy published_chunks on public.knowledge_chunks;
create policy read_documents on public.knowledge_documents for select to authenticated using (((select auth.jwt())->'app_metadata'->>'role')='admin' or active_version_id is not null);
create policy read_versions on public.knowledge_versions for select to authenticated using (((select auth.jwt())->'app_metadata'->>'role')='admin' or (published_at is not null and status='ready'));
create policy read_chunks on public.knowledge_chunks for select to authenticated using (((select auth.jwt())->'app_metadata'->>'role')='admin' or exists(select 1 from public.knowledge_versions v where v.id=version_id and v.published_at is not null and v.status='ready'));
create policy admin_insert on public.knowledge_documents for insert to authenticated with check (((select auth.jwt())->'app_metadata'->>'role')='admin');
create policy admin_update on public.knowledge_documents for update to authenticated using (((select auth.jwt())->'app_metadata'->>'role')='admin') with check (((select auth.jwt())->'app_metadata'->>'role')='admin');
create policy admin_delete on public.knowledge_documents for delete to authenticated using (((select auth.jwt())->'app_metadata'->>'role')='admin');
create policy admin_insert on public.knowledge_versions for insert to authenticated with check (((select auth.jwt())->'app_metadata'->>'role')='admin');
create policy admin_update on public.knowledge_versions for update to authenticated using (((select auth.jwt())->'app_metadata'->>'role')='admin') with check (((select auth.jwt())->'app_metadata'->>'role')='admin');
create policy admin_delete on public.knowledge_versions for delete to authenticated using (((select auth.jwt())->'app_metadata'->>'role')='admin');
create policy admin_insert on public.knowledge_chunks for insert to authenticated with check (((select auth.jwt())->'app_metadata'->>'role')='admin');
create policy admin_update on public.knowledge_chunks for update to authenticated using (((select auth.jwt())->'app_metadata'->>'role')='admin') with check (((select auth.jwt())->'app_metadata'->>'role')='admin');
create policy admin_delete on public.knowledge_chunks for delete to authenticated using (((select auth.jwt())->'app_metadata'->>'role')='admin');
